// th15_s4_b3 — TH15 v1.00b Stage 4 Boss2, 3rd nonspell (normal interrupt chain).
// Source: st04bs.ecl.txt:855-913 Boss2; deps 915-953 Boss2_at, 955-993 Boss2_at2,
// 180-329 BCir02/BCir02b, 222-294 BCir02_at/BCir02_at2.
// Card clock: OPENING_BUFFER(120) + 4-frame entry cleanup + 2520 source window = 2644.
// Source timerReset is at the end of the entry cleanup (line 871); entry ops below are omitted
// per the approved synthesis policy (chapter counter, drops, etClear/etCancel, funcSet(0),
// spellEnd, laserCancel, sound, move resets, lifeMarker/stars/anm).

const TIME_LIMIT: int = 2644;
const OPENING_BUFFER: int = 120;
const ENTRY_CLEANUP: int = 4;

// TH15 type 11 = talisman row base (copied from transcribe/th15/touhou-bullets.ecl).
const TH15_TALISMAN: int = 528;

// Source radian steps -> BAM: 0.261799 rad = 15deg = 2731, 0.05236 rad = 3deg = 546,
// 0.02618 rad = 1.5deg = 273.
const THETA_STEP: int = 2731;
const OMEGA_STEP: int = 546;
const SHOT_STEP: int = 273;

// ---------------------------------------------------------------------------
// Training shell: control carries the phase, real Boss2 at (0,128) is spawned
// after the 120-frame buffer (st04bs.ecl.txt:733 movePos(0,128)).
// ---------------------------------------------------------------------------

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 17100, 0, 0, 0, boss_main);
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------------------------------------------------------------------------
// Boss2 body: st04bs.ecl.txt:855-913.
// setInvuln(120)/lifeSet(17100) at entry: no-DPS shell keeps the boss invulnerable.
// Boxes come from the shared Boss() context (st04bs.ecl.txt:746-747):
// setHurtbox(40,40) -> r20, setHitbox(48,48) -> r24.
// ---------------------------------------------------------------------------

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    // +2/+2 time labels at lines 865/867: 4-frame entry cleanup, not part of source window.
    wait(ENTRY_CLEANUP);
    // line 895 wait(140) before the first wave; moveLimit(0,128,280,64) at line 896.
    wait(140);
    for cycle in 0..6 {
        boss_wave(0);          // Boss2_at  (lines 901-905)
        wait(20);
        boss_move_rand();      // moveRand(60,4,1.0)
        boss_wait(130);
        boss_wave(1);          // Boss2_at2 (lines 906-909)
        wait(20);
        boss_move_rand();
        boss_wait(130);
    }
    loop { wait(1); }
}

// Boss2_at / Boss2_at2 (lines 915-953 / 955-993).
// diffI($B,6,12,12,12) = 6 circles on Easy, 12 otherwise; spawn gap 10 (Easy) / 5.
// Every 4th slot is BCir02b (colour 6), the rest BCir02 (colour 2).
// %F0 starts at 0 and steps by -0.261799 (Boss2_at) / +0.261799 (Boss2_at2);
// Easy steps the phase twice per slot. %F1 = +/-0.05236, %F2 = 100, %F3 = +/-0.02618.
// %I0 starts 100 and drops by 5 per slot (dwell before the enemy leaves).
sub boss_wave(turn: int) {
    var rank: int = global(GVAR_RANK);
    var n: int = 12;
    var gap: int = 5;
    var per: int = THETA_STEP;
    if rank == RANK_EASY {
        n = 6;
        gap = 10;
        per = THETA_STEP * 2;
    }
    var sgn: int = 1;
    if turn != 0 { sgn = -1; }
    var theta0: int = 0;
    var i0: int = 100;
    for i in 0..n {
        var color: int = 2;
        if i % 4 == 0 { color = 6; }
        // enmCreate("BCir02"/"BCir02b", 0,0,...) relative to the boss FINAL position.
        _ = spawn_enemy($self_x, $self_y, 200, 0, 0, 0,
                        child_main(theta0, sgn * OMEGA_STEP, i0, color, $frame + 1));
        theta0 = theta0 - sgn * per;
        i0 = i0 - 5;
        wait(gap);
    }
}

// moveRand(60,4,1.0) with moveLimit(0,128,280,64): x in [-140,140], y in [96,160].
// Reused from the verified moveRand recipe (TH18 BossCard1 / TH16 BossCard2), with
// this card's limit: direction inner zone x +/-70, y 112..144; speed 1*(1-k/60).
sub boss_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    boss_arm_next();
}

sub boss_arm_next() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        boss_arm_next();
    }
}

// ---------------------------------------------------------------------------
// BCir02 / BCir02b child (lines 180-214 / 296-329).
// moveCircle(%F0,%F1,0,0) then moveCircleTime(120,0,-999999,%F2,0):
//   theta(t) = theta0 + omega*t; radius 0 -> 100 linearly over 120 updates, then 100;
//   radial speed stays 0. -999999 is the source "keep omega" sentinel.
// After 120+dwell frames: moveVel(FINAL_ANGLE, 3.0) and start BCir02_at2.
// The target has no enemy offscreen cull, so the source's flagClear(15) removal is
// reproduced by ending the main task once the enemy leaves the field plus margin.
// ---------------------------------------------------------------------------

async sub child_main(theta0: int, omega: int, dwell: int, color: int, t0: int) {
    // Approved: invulnerable survival path; BCir02Dead/BI3 damage feedback is not simulated.
    set_invuln(65535);
    set_hitbox(8fx);    // setHitbox(16,16)
    set_hurtbox(12fx);  // setHurtbox(24,24)
    // flagSet(15) covers the 120-frame fade-in: shared flag bit 0x2 disables body contact
    // until flagClear(15) at frame 120 (0x4/0x8 offscreen-skip is bounded by the cull below).
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var rank: int = global(GVAR_RANK);
    var shot_wait: int = 2;
    if rank == RANK_EASY || rank == RANK_NORMAL { shot_wait = 4; }
    if rank == RANK_HARD { shot_wait = 3; }
    var burst_gap: int = 15;
    if rank == RANK_LUNATIC { burst_gap = 5; }
    var leave_step: int = 120 + dwell;
    var s: int = 0;
    var f: int = 0;
    spawn child_at(color, theta0, omega, t0, omega / 2, shot_wait, leave_step);
    // Arm the next source movement tick while the radius expands / circle holds.
    while f < leave_step {
        s = f + 1;
        if f == 120 { set_enemy_flag(ENEMY_NO_BODY, 0); }
        var th: angle = (theta0 + omega * s) as angle;
        var rr: fx = 100fx;
        if s < 120 { rr = (100 * s) as fx / 120; }
        move_vel_xy(0, cx + rr * cos(th) - $self_x,
                       cy + rr * sin(th) - $self_y, EASE_LINEAR);
        f = f + 1;
        wait(1);
    }
    // FINAL_ANGLE = direction of the displacement just performed (P(leave)-P(leave-1)).
    var ths: angle = (theta0 + omega * leave_step) as angle;
    var thp: angle = (theta0 + omega * (leave_step - 1)) as angle;
    var rs: fx = 100fx;
    if leave_step < 120 { rs = (100 * leave_step) as fx / 120; }
    var rp: fx = 100fx;
    if leave_step - 1 < 120 { rp = (100 * (leave_step - 1)) as fx / 120; }
    var dx: fx = rs * cos(ths) - rp * cos(thp);
    var dy: fx = rs * sin(ths) - rp * sin(thp);
    var la: angle = atan2(dy, dx);
    move_vel(0, la, 3fx, EASE_LINEAR);
    spawn child_at2(color, la, omega / 2, burst_gap);
    loop {
        wait(1);
        if $self_x < -256fx || $self_x > 256fx || $self_y < -64fx || $self_y > 512fx {
            return;
        }
    }
}

// BCir02_at (lines 222-254): 400 shots, aimed along FINAL_ANGLE + %B, %B += %F3 per shot.
// wait 4/4/3/2 frames by difficulty. killAsync(1) at the end of the circle equals
// stop_step here (deterministic; no shared-slot ordering).
// Bullets: etSprite(0,11,color), etCount(0,1,1), etSpeed(0,2.0,0.2) -> single 2.0px/frame,
// etAim(0,3) fixed ring with N=1 -> exact base angle; ANIM a=1 birth displacement -4*velocity
// (shared EX semantics) is kept as an 8px backward offset.
async sub child_at(color: int, theta0: int, omega: int, t0: int, dstep: int,
                   step_wait: int, stop_step: int) {
    wait(10);
    var b: int = 0;
    var shot: int = 0;
    while shot < 400 {
        var s: int = $frame - t0;
        if s >= stop_step { return; }
        var ths: angle = (theta0 + omega * s) as angle;
        var thp: angle = (theta0 + omega * (s - 1)) as angle;
        var rs: fx = 100fx;
        if s < 120 { rs = (100 * s) as fx / 120; }
        var rp: fx = 100fx;
        if s - 1 < 120 { rp = (100 * (s - 1)) as fx / 120; }
        var dx: fx = rs * cos(ths) - rp * cos(thp);
        var dy: fx = rs * sin(ths) - rp * sin(thp);
        var a: angle = atan2(dy, dx) + (b as angle);
        _ = fire(TH15_TALISMAN, color,
                 $self_x - 8fx * cos(a), $self_y - 8fx * sin(a),
                 2fx, a, none, none);
        b = b + dstep;
        shot = shot + 1;
        wait(step_wait);
    }
}

// BCir02_at2 (lines 256-294): %B starts at %F3*60 (+/-90deg); 100 bursts of 8 shots
// every 5 frames, then wait 15 (E/N/H) or 5 (Lunatic). FINAL_ANGLE is the constant
// straight-line direction after moveVel.
async sub child_at2(color: int, la: angle, dstep: int, burst_gap: int) {
    wait(10);
    var b: int = dstep * 60;
    var burst: int = 0;
    while burst < 100 {
        var k: int = 0;
        while k < 8 {
            var a: angle = la + (b as angle);
            _ = fire(TH15_TALISMAN, color,
                     $self_x - 8fx * cos(a), $self_y - 8fx * sin(a),
                     2fx, a, none, none);
            b = b + dstep;
            k = k + 1;
            wait(5);
        }
        wait(burst_gap);
        burst = burst + 1;
    }
}
